{

    internal InnerDataAutomationProjectVideoStandardGenerativeFieldFactory GenerativeFieldFactory { get; set; }

    internal InnerDataAutomationProjectVideoStandardExtractionFactory ExtractionFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardOutputConfiguration Create()
    {
        var videoStandardOutputConfigurationResult = CreateVideoStandardOutputConfiguration();
        factoryAction?.Invoke(videoStandardOutputConfigurationResult);

        return videoStandardOutputConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardOutputConfiguration CreateVideoStandardOutputConfiguration()
    {
        var videoStandardOutputConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardOutputConfiguration();

        return videoStandardOutputConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.VideoStandardOutputConfiguration result)
    {
        base.CreateChildren(result);

        result.GenerativeField ??= GenerativeFieldFactory?.Build();
        result.Extraction ??= ExtractionFactory?.Build();
    }

} // End Of Class

